const unknown=(axis,historical)=>({axis,position:'Sin determinar',basis:historical?'No se verificó en las fuentes seleccionadas una posición personal comparable para este eje en el período estudiado. No se extrapolan opiniones sobre políticas posteriores.':'Las fuentes seleccionadas no permiten establecer una posición personal suficiente para este eje. La pertenencia partidaria no completa el dato.',refs:[],confidence:null,kind:'unknown',comparability:'none'});
export const ADDITIONAL_FIGURES=definitions.map(d=>{
 const keys=[...new Set([...d.sources,...d.known.flatMap(x=>x.refs.map(r=>r.key))])],sources=keys.map(k=>S[k]);
 const axisResearch=RESEARCH_AXES.map((_,i)=>d.known.find(x=>x.axis===i)||unknown(i,d.historical)).map(x=>({...x,refs:x.refs.map(r=>({source:keys.indexOf(r.key),page:r.page}))}));
 return {id:d.id,name:d.name,party:d.party,partyName:d.partyName,sector:d.sector,era:d.period,period:d.period,bio:d.bio,summary:d.bio,actions:[d.evolution],quotes:[],sources,
  profile:Array(12).fill(null),rationale:axisResearch.map(x=>x.basis),evidence:axisResearch.flatMap(x=>x.refs.map(r=>({...r,axis:x.axis,note:x.basis,confidence:x.confidence,kind:x.kind}))),
  axisResearch,orientation:d.orientation,role:d.role,evolution:d.evolution,historical:d.historical,researchOnly:true,eligible:false,rankEligible:false,comparable:false,cohort:'investigacion-22',editorial:true,
  comparisonNote:'Ficha documental con posiciones cualitativas y confianza por eje. No tiene afinidad numérica: sus fuentes y períodos todavía no cuentan con una calibración comparable en los cinco ejes del ranking. Los datos desconocidos no se sustituyen por neutralidad.',
  updatedAt:'2026-11-04'};
});
export const ADDITIONAL_PERSON_DETAILS=Object.fromEntries(ADDITIONAL_FIGURES.map(f=>[f.id,{party:f.partyName+(f.sector?' · '+f.sector:''),orientation:f.orientation,role:f.role}]));
